from pathlib import Path
import os,signal,subprocess
repo=Path('/Users/steventran/jobpipe')
base='591832cea7d132086751ab806d269f6e58f67bc0'
def git(*a):return subprocess.run(['git',*a],cwd=repo,check=True,capture_output=True,text=True).stdout.strip()
if git('rev-parse','HEAD')!=base or git('rev-parse','origin/main')!=base:raise SystemExit('AUTHORITY_CHANGED')
src=repo/'tools/ats_review_smoke.py';test=repo/'tests/test_ats_review_smoke.py'
for p in (src,test):
 if git('status','--porcelain','--',str(p.relative_to(repo))):raise SystemExit('TARGET_DIRTY')
s=src.read_text()
# Count-only can be fooled by unrelated passes. Require each ATS's Review case
# and at least one Gate-B/no-submit protection to report PASSED, not skipped.
anchor='''    good = rc == 0 and count >= 9 and not re.search(r"\\d+ skipped", output)'''
replacement='''    required = (
        "test_adapter_reaches_review_with_required_fields_and_upload[greenhouse-",
        "test_adapter_reaches_review_with_required_fields_and_upload[lever-",
        "test_adapter_reaches_review_with_required_fields_and_upload[ashby-",
        "test_adapter_reaches_review_with_required_fields_and_upload[jobvite-",
    )
    review_verified = all(
        any(required_name in line and " PASSED" in line
            for line in output.splitlines())
        for required_name in required
    )
    safeguard_verified = any(
        "test_submit_requires_gate_b" in line and " PASSED" in line
        for line in output.splitlines()
    )
    good = (rc == 0 and count >= 9
            and not re.search(r"\\d+ skipped", output)
            and review_verified and safeguard_verified)'''
if s.count(anchor)!=1:raise SystemExit('ANCHOR_CHANGED')
s=s.replace(anchor,replacement,1).replace('''"-q", "--tb=short", TEST,''','''"-q", "-v", "--tb=short", TEST,''',1)
src.write_text(s)
t=test.read_text()
t=t.replace('''return FakeProcess("9 passed in 1.0s", 0)''','''return FakeProcess(
            "\\n".join(
                f"tests/test_ats_adapter_contract.py::test_adapter_reaches_review_with_required_fields_and_upload[{name}-x] PASSED"
                for name in ("greenhouse","lever","ashby","jobvite")
            ) + "\\ntests/test_ats_adapter_contract.py::test_submit_requires_gate_b PASSED\\n9 passed in 1.0s", 0)''')
t+='''

def test_smoke_refuses_count_only_without_adapter_coverage(monkeypatch):
    class FakeProcess:
        returncode = 0
        def communicate(self, timeout=None):
            return "9 passed in 1.0s", None
    monkeypatch.setattr(ats_review_smoke.subprocess, "Popen", lambda *a, **k: FakeProcess())
    assert ats_review_smoke.main() != 0
'''
test.write_text(t)
def run(args,seconds):
 p=subprocess.Popen(args,cwd=repo,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
 try:o,e=p.communicate(timeout=seconds)
 except subprocess.TimeoutExpired:
  os.killpg(p.pid,signal.SIGTERM)
  try:o,e=p.communicate(timeout=8)
  except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);o,e=p.communicate()
  print('TIMEOUT',o[-1700:],flush=True);raise SystemExit(124)
 print('RESULT',p.returncode,o[-4500:],e[-500:],flush=True)
 return p.returncode,o
rc,_=run([str(repo/'.venv/bin/python'),'-m','pytest','-q','tests/test_ats_review_smoke.py'],95)
if rc:raise SystemExit('GATE_TEST_FAILURE')
rc,out=run([str(repo/'.venv/bin/python'),'tools/ats_review_smoke.py'],400)
if rc or 'ATS_FIXTURE_REVIEW_GATE=PASS' not in out:raise SystemExit('SMOKE_FAILURE')
subprocess.run(['git','add','--','tools/ats_review_smoke.py','tests/test_ats_review_smoke.py'],cwd=repo,check=True)
subprocess.run(['git','commit','-m','fix: require per-ATS Review proof in no-submit smoke gate'],cwd=repo,check=True)
subprocess.run(['git','push','origin','main'],cwd=repo,check=True,timeout=90)
print('VERIFIED_PUSH',git('rev-parse','HEAD'),flush=True)
